const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
const text = buf.toString('latin1');

// Find the exact world_meta data
// SQLite pages: look for keys around cs_policies_checked
const idx = text.indexOf('cs_policies_checked');
const start = Math.max(0, idx - 100);
const end = Math.min(text.length, idx + 200);
const region = text.substring(start, end);
// Print hex + ascii  
for (let i = start; i < end; i += 16) {
  const hex = [];
  const ascii = [];
  for (let j = 0; j < 16 && (i+j) < end; j++) {
    const code = buf[i+j];
    hex.push(code.toString(16).padStart(2, '0'));
    ascii.push(code >= 32 && code < 127 ? String.fromCharCode(code) : '.');
  }
  console.log(hex.join(' ') + '  ' + ascii.join(''));
}
"
